-- Wächter Migration 198 (nur lesen). Erwartungen: werkzeuge/m198_md5.json. schema = ally_cd, ally_cd_dateien, ally_postfaecher, ally_systemnachricht_absender,
-- ally_systemnachrichten, postfach_plaetze (ändert sich nicht); funktionen = Fingerabdruck ally_systemnachricht_absender_stand, ally_systemnachricht_ui_aktion,
-- ally_systemnachrichten_holen, ally_web_cd_datei; typ = talents_zahlen_zeile vorhanden (t/f); nr_ab_11 = nächste Postfach-Nummer ≥ 11 (t/f).
SELECT (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_cd', 'ally_cd_dateien', 'ally_postfaecher', 'ally_systemnachricht_absender', 'ally_systemnachrichten', 'postfach_plaetze'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) AS schema, (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_systemnachricht_absender_stand', 'ally_systemnachricht_ui_aktion', 'ally_systemnachrichten_holen', 'ally_web_cd_datei'])) AS funktionen, (to_regtype('public.talents_zahlen_zeile') IS NOT NULL) AS typ, ((SELECT CASE WHEN s.is_called THEN s.last_value + q.seqincrement ELSE s.last_value END FROM public.postfach_nr_seq s, pg_sequence q WHERE q.seqrelid = 'public.postfach_nr_seq'::regclass) >= 11) AS nr_ab_11;
